"""Write outputs/ (spec 9.1-9.4). Generated by `make outputs`; never edit the files by hand."""
import csv
import json
import pathlib

import yaml

from engine import household as h
from engine import population as pop
from engine import reforms as r
from engine import wall_map as w

OUT = pathlib.Path(__file__).resolve().parents[1] / "outputs"
HOUSEHOLDS = [f"H{i}" for i in range(1, 9)]
DESIGNS = ["government_final", "rengo", "daiwa", "food_tax_cut"]

BASELINE = OUT.parent / "parameters" / "baseline_2026"


def approximations(node, where):
    """Every baseline approximation (CLAUDE.md rule 3), in the plain words the site shows next to the numbers."""
    if isinstance(node, dict):
        if node.get("approximation") is True:
            assert "site" in node, f"{where}: an approximation needs `site: {{ja, en}}` text for the website"
            yield node["site"]
        for k, v in node.items():
            yield from approximations(v, f"{where}.{k}")
    else:
        assert not (isinstance(node, str) and node.startswith("approximation: true")), f"{where}: use approximation: true with site text"


OUT.mkdir(exist_ok=True)
rows = []
for hid in HOUSEHOLDS:
    hh = h.load(hid)
    for d in DESIGNS:
        res = r.run(d, hh)
        rows.append({"household": hid, "baseline_disposable": h.compute(hh)["disposable"],
                     "label": r.design(d)["label"], **res})
(OUT / "household_comparison.json").write_text(json.dumps(rows, ensure_ascii=False, indent=1))
with open(OUT / "household_comparison.csv", "w", newline="") as f:
    cols = ["household", "design", "status", "baseline_disposable", "disposable_change", *r.COMPONENTS, "missing"]
    wr = csv.DictWriter(f, cols)
    wr.writeheader()
    for x in rows:
        wr.writerow({**{k: x.get(k) for k in cols}, **x["components"], "missing": "; ".join(x["missing"])})

walls = {"step": w.STEP, "columns": ["income", "disposable", "emr"], "households": {}, "skipped": {},
         "labels": {"baseline": {"ja": "2026年の制度", "en": "2026 rules"}, **{d: r.design(d)["label"] for d in DESIGNS}},
         "summaries": {d: r.design(d)["summary"] for d in DESIGNS}, "shorts": {d: r.design(d)["short"] for d in DESIGNS},
         # the same text shared by several parameters (a YAML alias) is listed once
         "baseline_approximations": list({json.dumps(a, ensure_ascii=False): a for f in sorted(BASELINE.glob("*.yaml"))
                                          for a in approximations(yaml.safe_load(f.read_text(encoding="utf-8")), f.stem)}.values())}
for hid in HOUSEHOLDS:
    hh = h.load(hid)
    who = w.varying_member(hh)
    if who is None:
        walls["skipped"][hid] = "two incomes: which member's income moves is pending HUMAN_TODO H-11"
        continue
    designs = {}
    for d in ["baseline"] + DESIGNS:
        if d != "baseline" and r.run(d, hh)["status"] == "incomplete":
            walls["not_drawn"] = {**walls.get("not_drawn", {}), d: r.run(d, hh)["blocked_by"]}
            continue
        designs[d] = [[p["income"], p["disposable"], p["emr"]] for p in w.grid(hh, d)]
    walls["households"][hid] = {"member": who[0], "income_field": who[1], "name_ja": hh["name_ja"],
                                "member_role": next(m["role"] for m in hh["members"] if m["id"] == who[0]),
                                "couple": any(m["role"] == "spouse" for m in hh["members"]),
                                "reference_income": next(m for m in hh["members"] if m["id"] == who[0])[who[1]],
                                "incomes": [{k: m[k] for k in ("role", "age", "salary", "business_income", "public_pension") if m.get(k)}
                                            for m in hh["members"]],
                                "name_en": hh["name_en"], "assumptions": hh.get("assumptions", []), "designs": designs}
(OUT / "wall_map.json").write_text(json.dumps(walls, ensure_ascii=False, separators=(",", ":")))
# population view and cost (spec 9.3, 9.4): every number here is an approximation and is labelled so on the site
p = pop.results(DESIGNS)
hh_rows = p.pop("households_csv_rows")
p["approximations"] = [{"key": k, "ja": v["ja"], "en": v["en"]} for k, v in pop.config()["assumptions"].items()]
p["groups"] = {k: {"ja": v["ja"], "en": v["en"]} for k, v in pop.config()["groups"].items()}
p["sources"] = pop.config()["sources"]
(OUT / "population.json").write_text(json.dumps(p, ensure_ascii=False, indent=1, default=str))
with open(OUT / "population_households.csv", "w", newline="") as f:
    wr = csv.DictWriter(f, list(hh_rows[0]))
    wr.writeheader()
    wr.writerows(hh_rows)
# design builder (Milestone 8): the browser adds the custom credit to these 2026 numbers (site/custom.js)
built = pop.build()
builder = {"households": {}, "population": {
    "rows": [r.people(x["household"]) for x in built],
    "pieces": [[i, d, round(wt, 2)] for i, d, wt in pop.decile_pieces([(i, x["cell"]["annual_income"], x["weight"]) for i, x in enumerate(built)])]}}
for hid in walls["households"]:
    hh = h.load(hid)
    mid, field = w.varying_member(hh)
    i = next(k for k, m in enumerate(hh["members"]) if m["id"] == mid)
    ppl, slot = r.people(hh), 2 if field == "public_pension" else 1
    builder["households"][hid] = {"people": ppl, "vary": [i, slot, ppl[i][slot] - hh["members"][i].get(field, 0)]}
(OUT / "builder.json").write_text(json.dumps(builder, separators=(",", ":")))
print(f"wrote {len(rows)} comparison rows, wall maps for {list(walls['households'])}, skipped {list(walls['skipped'])}, {len(hh_rows)} population households")

# corrections log (spec 10, page 8), read by site/corrections.html
log = yaml.safe_load((OUT.parent / "docs" / "CORRECTIONS.yaml").read_text(encoding="utf-8"))
(OUT / "corrections.json").write_text(json.dumps(log, ensure_ascii=False, indent=1, default=str))
